/// Per butterfly:
/// sum  = vj + vjl
/// diff = vjl - vj
/// out_lo = sum                        (no reduction: whittle schedule)
/// out_hi = barrett_const_mul(diff, zeta, zeta_bar)          (3 vec ops)
///
